        {{ null_junk('"ENTY_NAML"') }} as enty_naml,
        {{ null_junk('"ENTY_NAMS"') }} as enty_nams,
        {{ null_junk('"ENTY_NAMT"') }} as enty_namt,
        {{ null_junk('"ENTY_TITLE"') }} as enty_title,
        {{ null_junk('"FILING_ID"') }} as filing_id,
        {{ null_junk('"FORM_TYPE"') }} as form_type,
        {{ stg_int('"LINE_ITEM"') }} as line_item,
        {{ null_junk('"REC_TYPE"') }} as rec_type,
        {{ null_junk('"TRAN_ID"') }} as tran_id,
        INGESTED_AT as _loaded_at,
